1|// Cleaning: strip front/back junk before segmentation. Pure: no env reads,
2|// no network. The LLM arrives as an injected judge; tests pass fakes.
3|// Rules live in clean-rules.ts, shared types in clean-types.ts.
4|export type {
5|  CleanChapter,
6|  CleanReport,
7|  Judge,
8|  JudgeInput,
9|  JudgeResult,
10|  JudgeSectionInput,
11|  JudgeVerdict,
12|  JudgeVerdictLabel,
13|  JudgeWindowBlock,
