47|const HEAD_WINDOW = 6;
48|const TAIL_WINDOW = 8;
49|const LONG_SECTION_WORDS = 2000;
50|
51|function buildJudgeInput(kept: RawSection[], ambiguous: RawSection[], bookTitle: string): JudgeInput {
52|  const first = kept[0];
53|  const last = kept[kept.length - 1];
54|  return {
55|    sections: ambiguous.map((sec) => ({
56|      id: sec.id,
57|      title: deriveTitle(sec, bookTitle),
58|      words: sectionWords(sec),
59|      head: sec.blocks.slice(0, 2).map((b) => short(b.text, 200)),
60|      tail: sec.blocks.slice(-2).map((b) => short(b.text, 200)),
61|    })),
62|    headWindow: (first?.blocks.slice(0, HEAD_WINDOW) ?? []).map((b, index) => ({ index, text: short(b.text, 200) })),
63|    tailWindow: (last?.blocks.slice(-TAIL_WINDOW) ?? []).map((b, index) => ({ index, text: short(b.text, 200) })),
64|  };
