67|export async function cleanSections(
68|  bookTitle: string,
69|  sections: RawSection[],
70|  judge?: Judge,
71|): Promise<{ chapters: CleanChapter[]; report: CleanReport }> {
72|  const removed: RemovedItem[] = [];
73|  const flagged: CleanReport["flagged"] = [];
74|  const merged: CleanReport["merged"] = [];
75|  const pushRemoved = (sec: RawSection, rule: string, kind: string, reason: string): void => {
76|    removed.push(removedFor(sec, rule, kind, reason));
77|  };
78|
79|  let kept = sections.filter((sec) => {
80|    if (!sec.linear) {
81|      pushRemoved(sec, "linear-no", "non_content", 'linear="no" spine item');
82|      return false;
83|    }
84|    return true;
85|  });
86|  kept = kept.filter((sec) => {
87|    const hit = ruleEpubType(sec);
88|    if (hit !== null) {
89|      pushRemoved(sec, "epub-type", hit.kind, hit.reason);
90|      return false;
91|    }
92|    return true;
93|  });
94|  kept = mergeContinuations(kept, merged);
95|  const dropSimple = (rule: (sec: RawSection) => { kind: string; reason: string } | null, name: string): void => {
96|    kept = kept.filter((sec) => {
97|      const hit = rule(sec);
98|      if (hit !== null) {
99|        pushRemoved(sec, name, hit.kind, hit.reason);
100|        return false;
101|      }
102|      return true;
103|    });
104|  };
105|  dropSimple(ruleEmpty, "empty");
106|  dropSimple(rulePgMarkers, "pg-markers");
107|  const confident = new Set(kept.filter(isConfident).map((sec) => sec.id));
108|  const skipConfident = (
109|    rule: (sec: RawSection) => { kind: string; reason: string } | null,
110|    name: string,
111|  ): void => {
112|    kept = kept.filter((sec) => {
113|      if (confident.has(sec.id)) return true;
114|      const hit = rule(sec);
115|      if (hit !== null) {
116|        pushRemoved(sec, name, hit.kind, hit.reason);
117|        return false;
118|      }
119|      return true;
120|    });
121|  };
122|  skipConfident(ruleTitlePolicy(bookTitle), "title-policy");
123|  skipConfident(ruleContentsBody(bookTitle, kept), "contents-body");
124|  skipConfident(ruleAdBody, "ad-body");
125|
126|  let llm: CleanReport["llm"] = null;
127|  const ambiguous = kept.filter((sec) => !confident.has(sec.id));
128|  if (ambiguous.length > 0 && judge !== undefined) {
129|    let result: JudgeResult | null = null;
130|    try {
131|      result = await judge(buildJudgeInput(kept, ambiguous, bookTitle));
132|    } catch {
133|      result = null;
134|    }
135|    if (result === null) {
136|      llm = { model: "unknown", promptTokens: 0, completionTokens: 0, cachedTokens: 0, costUsd: 0, error: "failed" };
137|    } else {
138|      llm = {
139|        provider: result.provider,
140|        model: result.model,
141|        promptTokens: result.promptTokens,
142|        completionTokens: result.completionTokens,
143|        cachedTokens: result.cachedTokens,
144|        costUsd: result.costUsd,
145|        fallbackUsed: result.fallbackUsed,
146|      };
147|      const byId = new Map(result.sections.map((v) => [v.id, v]));
148|      const contentIds = new Set(
149|        ambiguous.filter((sec) => byId.get(sec.id)?.verdict === "content" || confident.has(sec.id)).map((sec) => sec.id),
150|      );
151|      for (const c of kept) if (confident.has(c.id)) contentIds.add(c.id);
152|      const after: RawSection[] = [];
153|      ambiguous.forEach((sec) => {
154|        const verdict = byId.get(sec.id);
155|        if (verdict === undefined || verdict.verdict === "content") {
156|          after.push(sec);
157|          return;
158|        }
159|        if (verdict.verdict === "uncertain") {
160|          flagged.push({ sectionId: sec.id, reason: short(verdict.reason, 120) });
161|          after.push(sec);
162|          return;
163|        }
164|        const at = kept.indexOf(sec);
165|        const before = kept.slice(0, at).some((s) => contentIds.has(s.id));
166|        const behind = kept.slice(at + 1).some((s) => contentIds.has(s.id));
167|        if (sectionWords(sec) >= LONG_SECTION_WORDS && before && behind) {
168|          flagged.push({ sectionId: sec.id, reason: short(`long interior section kept despite verdict: ${verdict.reason}`, 120) });
169|          after.push(sec);
170|          return;
171|        }
172|        pushRemoved(sec, "llm", verdict.kind, verdict.reason);
173|      });
174|      const keptIds = new Set(after.map((s) => s.id).concat([...confident]));
175|      kept = kept.filter((sec) => confident.has(sec.id) || keptIds.has(sec.id));
176|      const headCut = Math.max(0, Math.min(Math.floor(result.headCut), HEAD_WINDOW));
177|      const tailCut = Math.max(0, Math.min(Math.floor(result.tailCut), TAIL_WINDOW));
178|      if (kept.length > 0 && headCut > 0) {
179|        const firstKept = kept[0];
180|        if (firstKept !== undefined) {
181|          const cut = Math.min(headCut, firstKept.blocks.length);
182|          if (cut > 0) {
183|            removed.push(removedFor(firstKept, "llm", "edge_trim", "judge headCut", [0, cut - 1]));
184|            kept = [{ ...firstKept, blocks: firstKept.blocks.slice(cut) }, ...kept.slice(1)];
185|          }
186|        }
187|      }
188|      if (kept.length > 0 && tailCut > 0) {
189|        const lastKept = kept[kept.length - 1];
190|        if (lastKept !== undefined) {
191|          // The judge counts from the untrimmed tail, so its cut can cover
192|          // blocks rule 10 removes right after. Cut only the fresh middle
193|          // and skip the entry entirely when nothing fresh remains. Head
194|          // cuts need no guard: no deterministic rule trims heads.
195|          const overlap = deterministicTailOverlap(kept, kept.length - 1);
196|          const start = Math.max(0, lastKept.blocks.length - tailCut);
197|          const end = lastKept.blocks.length - overlap;
198|          if (end > start) {
199|            removed.push(removedFor(lastKept, "llm", "edge_trim", "judge tailCut", [start, end - 1]));
200|            kept = [
201|              ...kept.slice(0, -1),
202|              { ...lastKept, blocks: [...lastKept.blocks.slice(0, start), ...lastKept.blocks.slice(end)] },
203|            ];
204|          }
205|        }
206|      }
207|    }
208|  }
209|
210|  kept = kept.map((sec) => stripPrinterLines(sec, removed));
211|  kept = applyTailCut(kept, removed);
212|  const chapters: CleanChapter[] = [];
213|  for (const sec of kept) {
214|    const title = deriveTitle(sec, bookTitle);
215|    const paragraphs = toParagraphs(sec, title);
216|    if (paragraphs.length === 0) {
217|      pushRemoved(sec, "block-drop", "empty", "no paragraphs after block drop");
218|      continue;
219|    }
220|    chapters.push({ title, paragraphs, sectionIds: [sec.id] });
221|  }
222|  return {
223|    chapters,
224|    report: {
225|      source: "epub",
226|      llm,
227|      kept: chapters.map((c) => ({ title: c.title, paragraphs: c.paragraphs.length, sectionIds: c.sectionIds })),
228|      removed,
229|      flagged,
230|      merged,
231|    },
232|  };
233|}
