1|// Client-safe EPUB parser: fflate plus the platform DOMParser, no node
2|// imports, so the home upload page can run it in the browser.
3|import { unzipSync } from "fflate";
4|
5|export const MAX_EPUB_BYTES = 20 * 1024 * 1024;
6|const MAX_ENTRY_BYTES = 8 * 1024 * 1024;
7|const MAX_INFLATED_BYTES = 60 * 1024 * 1024;
8|
9|export type EpubErrorCode = "not_epub" | "too_large" | "drm" | "unreadable";
10|
11|export class EpubError extends Error {
12|  code: EpubErrorCode;
13|  constructor(code: EpubErrorCode) {
14|    super(code);
15|    this.name = "EpubError";
16|    this.code = code;
17|  }
18|}
19|
20|export const EPUB_ERROR_MESSAGES: Record<EpubErrorCode, string> = {
21|  not_epub: "That doesn't look like an EPUB. Try a file that ends in .epub.",
22|  too_large: "That file is bigger than 20 MB. Most novels are far smaller, so try another edition.",
23|  drm: "This book is copy-protected, so we can't open it. Free classics from Project Gutenberg or Standard Ebooks work well.",
24|  unreadable: "We couldn't read this EPUB. It might be damaged. Try another copy.",
25|};
26|
27|export interface EpubBook {
28|  title: string;
29|  author: string | null;
30|  chapters: string[];
31|  words: number;
32|  cover: { bytes: Uint8Array; mediaType: string } | null;
33|}
34|
35|const FONT_ALGORITHMS = new Set([
36|  "http://www.idpf.org/2008/embedding",
37|  "http://ns.adobe.com/pdf/enc#RC",
38|]);
39|
40|const COVER_TYPES = new Set(["image/jpeg", "image/png", "image/gif", "image/webp"]);
41|const WORD_RE = /[\p{L}\p{N}]+(?:['’][\p{L}]+)*/gu;
42|
43|// Zip-bomb guard, checked in the inflate filter so big entries never load.
44|export function assertEntrySize(originalSize: number | undefined): void {
45|  if (typeof originalSize === "number" && originalSize > MAX_ENTRY_BYTES) {
46|    throw new EpubError("unreadable");
47|  }
48|}
49|
50|function inflateOnly(zip: Uint8Array, names: Set<string>): Record<string, Uint8Array> {
51|  const out = unzipSync(zip, {
52|    filter: (file) => {
53|      if (!names.has(file.name)) return false;
54|      assertEntrySize(file.originalSize);
55|      return true;
56|    },
57|  }) as Record<string, Uint8Array>;
58|  for (const name of Object.keys(out)) assertEntrySize(out[name]?.length);
59|  return out;
60|}
61|
62|function parseXml(text: string): Document {
63|  let doc: Document;
64|  try {
65|    doc = new DOMParser().parseFromString(text, "application/xml");
66|  } catch {
67|    throw new EpubError("unreadable");
68|  }
69|  if (doc.getElementsByTagName("parsererror").length > 0) throw new EpubError("unreadable");
70|  return doc;
71|}
72|
73|function elsByLocal(scope: Document | Element, local: string): Element[] {
74|  const found = scope.getElementsByTagName("*");
75|  const out: Element[] = [];
76|  for (let i = 0; i < found.length; i++) {
77|    const el = found[i];
78|    if (el && el.localName === local) out.push(el);
79|  }
80|  return out;
81|}
82|
83|function directChildren(el: Element, local: string): Element[] {
84|  return Array.from(el.children).filter((child) => child.localName === local);
85|}
86|
87|function clean(text: string | null | undefined): string {
88|  return (text ?? "").replace(/\s+/g, " ").trim();
89|}
90|
91|// Gutenberg boilerplate (front matter, edition notices) carries no story.
92|function normLabel(text: string): string {
93|  return text
94|    .toLowerCase()
95|    .replace(/[^a-z0-9\s]/g, "")
96|    .replace(/\s+/g, " ")
97|    .trim();
98|}
99|
100|function isFrontMatter(label: string, title: string): boolean {
101|  const norm = normLabel(label);
102|  if (norm === "contents" || norm === "table of contents") return true;
103|  if (norm.includes("project gutenberg")) return true;
104|  const normTitle = normLabel(title);
105|  if (normTitle.length > 0 && norm === normTitle) return true;
106|  return false;
107|}
