109|function decode(bytes: Uint8Array): string {
110|  return new TextDecoder().decode(bytes);
111|}
112|
113|// OPF hrefs resolve against the OPF directory; decode %20 and drop #fragments.
114|function resolveHref(opfPath: string, href: string): string {
115|  let path = href.split("#")[0] ?? "";
116|  try {
117|    path = decodeURIComponent(path);
118|  } catch {
119|    // Keep the raw path when decoding fails.
120|  }
121|  const dir = opfPath.includes("/") ? opfPath.slice(0, opfPath.lastIndexOf("/") + 1) : "";
122|  const parts: string[] = [];
123|  for (const seg of (dir + path).split("/")) {
124|    if (seg === "" || seg === ".") continue;
125|    if (seg === "..") parts.pop();
126|    else parts.push(seg);
127|  }
128|  return parts.join("/");
129|}
