131|function hasTocType(el: Element): boolean {
132|  const direct = el.getAttribute("epub:type") ?? el.getAttribute("type") ?? "";
133|  if (direct.split(/\s+/).includes("toc")) return true;
134|  for (let i = 0; i < el.attributes.length; i++) {
135|    const attr = el.attributes[i];
136|    if (attr && attr.localName === "type" && attr.value.split(/\s+/).includes("toc")) return true;
137|  }
138|  return false;
139|}
140|
141|function navChapters(doc: Document): string[] | null {
142|  const nav = elsByLocal(doc, "nav").find(hasTocType);
143|  const ol = nav ? elsByLocal(nav, "ol")[0] : undefined;
144|  if (!ol) return null;
145|  const labels = directChildren(ol, "li").map((li) => clean(elsByLocal(li, "a")[0]?.textContent));
146|  const kept = labels.filter((label) => label.length > 0);
147|  return kept.length > 0 ? kept : null;
148|}
149|
150|function ncxChapters(doc: Document): string[] {
151|  const map = elsByLocal(doc, "navMap")[0];
152|  if (!map) return [];
153|  return directChildren(map, "navPoint")
154|    .map((point) => clean(elsByLocal(directChildren(point, "navLabel")[0] ?? point, "text")[0]?.textContent))
155|    .filter((label) => label.length > 0);
156|}
157|
158|// Counts every word; long books route to BYOK in the UI, never an error.
159|function countWords(text: string, start: number): number {
160|  WORD_RE.lastIndex = 0;
161|  let count = start;
162|  let match: RegExpExecArray | null;
163|  while ((match = WORD_RE.exec(text)) !== null && match[0].length > 0) {
164|    count += 1;
165|  }
166|  return count;
167|}
168|
169|function bodyText(doc: Document): string {
170|  return elsByLocal(doc, "body")[0]?.textContent ?? doc.documentElement?.textContent ?? "";
171|}
172|
173|function spineText(docText: string): string {
174|  try {
175|    return bodyText(parseXml(docText));
176|  } catch {
177|    const doc = new DOMParser().parseFromString(docText, "text/html");
178|    return bodyText(doc);
179|  }
