184|  if (bytes[0] !== 0x50 || bytes[1] !== 0x4b || bytes[2] !== 0x03 || bytes[3] !== 0x04) {
185|    throw new EpubError("not_epub");
186|  }
187|
188|  let first: Record<string, Uint8Array>;
