190|    first = inflateOnly(
191|      bytes,
192|      new Set(["mimetype", "META-INF/container.xml", "META-INF/encryption.xml", "META-INF/rights.xml"]),
193|    );
194|  } catch (err) {
195|    if (err instanceof EpubError) throw err;
196|    throw new EpubError("unreadable");
197|  }
198|
199|  const mimetype = first["mimetype"] ? clean(decode(first["mimetype"] as Uint8Array)) : "";
200|  if (mimetype !== "application/epub+zip") throw new EpubError("not_epub");
201|  if (first["META-INF/rights.xml"]) throw new EpubError("drm");
202|
203|  const encryption = first["META-INF/encryption.xml"];
204|  if (encryption) {
205|    const doc = parseXml(decode(encryption));
206|    for (const method of elsByLocal(doc, "EncryptionMethod")) {
207|      if (!FONT_ALGORITHMS.has(method.getAttribute("Algorithm") ?? "")) throw new EpubError("drm");
208|    }
209|  }
210|
211|  const container = first["META-INF/container.xml"];
212|  if (!container) throw new EpubError("unreadable");
213|  const opfPath = elsByLocal(parseXml(decode(container)), "rootfile")[0]?.getAttribute("full-path");
214|  if (!opfPath) throw new EpubError("unreadable");
215|
216|  let opfBytes: Record<string, Uint8Array>;
217|  try {
218|    opfBytes = inflateOnly(bytes, new Set([opfPath]));
219|  } catch (err) {
220|    if (err instanceof EpubError) throw err;
221|    throw new EpubError("unreadable");
222|  }
223|  const opfRaw = opfBytes[opfPath];
224|  if (!opfRaw) throw new EpubError("unreadable");
225|  const opf = parseXml(decode(opfRaw));
226|
227|  const manifest = new Map<string, { href: string; mediaType: string; properties: string }>();
228|  for (const item of elsByLocal(opf, "item")) {
229|    const id = item.getAttribute("id");
230|    const href = item.getAttribute("href");
