5|export function countWords(text: string): number {
6|  return text.split(/\s+/).filter((w) => w.length > 0).length;
7|}
8|
9|export function sectionWords(sec: Pick<RawSection, "blocks">): number {
10|  return sec.blocks.reduce((n, b) => n + countWords(b.text), 0);
11|}
12|
13|export function short(text: string, max: number): string {
14|  return text.length <= max ? text : text.slice(0, max);
15|}
16|
17|export function removedFor(
18|  sec: RawSection,
19|  rule: string,
20|  kind: string,
21|  reason: string,
22|  blockRange: [number, number] | null = null,
23|): RemovedItem {
24|  const texts =
25|    blockRange === null ? sec.blocks.map((b) => b.text) : sec.blocks.slice(blockRange[0], blockRange[1] + 1).map((b) => b.text);
26|  return {
27|    sectionId: sec.id,
28|    blockRange,
29|    kind,
30|    reason: short(reason, 120),
31|    rule,
32|    words: texts.reduce((n, t) => n + countWords(t), 0),
33|    preview: short(texts[0] ?? "", 120),
34|  };
