60|  const kept: RawSection[] = [];
61|  for (const sec of sections) {
62|    const prev = kept[kept.length - 1];
63|    if (
64|      prev !== undefined &&
65|      sec.docTitle !== null &&
66|      sec.docTitle === prev.docTitle &&
67|      sec.blocks.every((b) => !b.heading) &&
68|      sectionWords(sec) <= 30
69|    ) {
70|      kept[kept.length - 1] = { ...prev, blocks: [...prev.blocks, ...sec.blocks] };
71|      merged.push({ from: sec.id, into: prev.id, reason: `no headings, ${sectionWords(sec)} words, same docTitle` });
