239|  if (/\b\d+\s*s\.(?:\s*\d+\s*d\.)?\s*net\b/i.test(t)) return true; // 6s. net
240|  if (/^\s*net\s*\.?\s*$/i.test(t)) return true; // a whole block reading net
241|  if (/crown\s+8vo/i.test(t)) return true;
242|  if (/in\s+one\s+volume/i.test(t)) return true;
243|  if (/\bprice\b/i.test(t)) return true;
244|  if (/[—–]\s*[“"]/.test(t)) return true; // GLOBE.—"quote"
