259|
260|const CHAPTER_LABEL = /^(?:chapter|stave|book|part)\s+[ivxlc0-9]+[.:]?\b/i;
261|const BARE_NUMERAL = /^(?:[ivxlc]+|\d+)[.:]?$/i;
262|
263|// Rule 9: confident content skips keyword rules 5-7 and the LLM.
264|export function isConfident(sec: RawSection): boolean {
265|  const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.trim());
266|  if (heads.some((h) => CHAPTER_LABEL.test(h))) return true;
267|  if (sec.navLabel !== null && sec.navLabel.includes(":")) {
268|    if (heads.some((h) => BARE_NUMERAL.test(h))) return true;
269|  }
270|  return false;
