272|
273|const END_MARK = /^(THE END|FINIS)\.?$/i;
274|const PRINTER_PATTERNS = [
275|  /^printed\s+(by|in)\b/i,
276|  /&\s*sons,?\s+limited/i,
277|  /r\.\s*&\s*r\.\s*clark/i,
278|  /limited,?\s+(london|edinburgh)\b/i,
279|];
280|
281|// Suffix length of the last kept section that rule 10 removes right after
282|// the judge runs: trailing printer lines, the THE END/FINIS block plus
283|// everything after it, or the whole section when it sits past the END
284|// mark with no confident section after it.
285|export function deterministicTailOverlap(kept: RawSection[], lastIdx: number): number {
286|  const last = kept[lastIdx];
287|  if (last === undefined) return 0;
288|  const { endSec, endIdx } = findEndMark(kept);
289|  if (endSec !== -1 && lastIdx > endSec && !kept.slice(endSec + 1).some(isConfident)) {
290|    return last.blocks.length;
291|  }
292|  let overlap = 0;
293|  while (
294|    overlap < last.blocks.length &&
295|    PRINTER_PATTERNS.some((p) => p.test(last.blocks[last.blocks.length - 1 - overlap]?.text.trim() ?? ""))
296|  ) {
297|    overlap += 1;
298|  }
299|  if (endSec === lastIdx) {
300|    overlap = Math.max(overlap, last.blocks.length - endIdx);
301|  }
302|  return overlap;
303|}
304|
305|// Last THE END/FINIS mark across kept sections, if any.
306|function findEndMark(kept: RawSection[]): { endSec: number; endIdx: number } {
307|  let endSec = -1;
308|  let endIdx = -1;
309|  kept.forEach((sec, i) => {
310|    const idx = sec.blocks.map((b) => b.text.trim()).findLastIndex((t) => END_MARK.test(t));
311|    if (idx !== -1) {
312|      endSec = i;
313|      endIdx = idx;
314|    }
315|  });
316|  return { endSec, endIdx };
317|}
318|
319|// Rule 10: cut from the last THE END/FINIS mark in any kept section,
320|// mark included (Cottage Folk hides it mid-file with ad pages below),
321|// and drop every later section, unless a later section carries a
322|// confident chapter heading. Trailing printer lines go separately in
323|// every kept section. Printer lines hide mid-list too (a merged "Sussex."
324|// + printer line lands in a story the ad sections below used to follow).
325|// Sign-offs stay.
326|export function applyTailCut(kept: RawSection[], removed: RemovedItem[]): RawSection[] {
327|  const { endSec, endIdx } = findEndMark(kept);
328|  if (endSec === -1) return kept;
329|  const endSection = kept[endSec];
330|  if (endSection === undefined) return kept;
331|  const out = kept.slice(0, endSec + 1);
332|  removed.push(removedFor(endSection, "tail-cut", "back_matter", "from THE END", [endIdx, endSection.blocks.length - 1]));
333|  out[endSec] = { ...endSection, blocks: endSection.blocks.slice(0, endIdx) };
334|  const later = kept.slice(endSec + 1);
335|  if (later.some(isConfident)) return [...out, ...later];
336|  for (const sec of later) {
337|    removed.push(removedFor(sec, "tail-cut", "back_matter", "after THE END"));
338|  }
339|  return out;
340|}
341|
342|export function stripPrinterLines(sec: RawSection, removed: RemovedItem[]): RawSection {
343|  let end = sec.blocks.length;
344|  while (end > 0 && PRINTER_PATTERNS.some((p) => p.test(sec.blocks[end - 1]?.text.trim() ?? ""))) {
345|    end -= 1;
346|  }
347|  if (end === sec.blocks.length) return sec;
348|  removed.push(removedFor(sec, "tail-cut", "back_matter", "printer line", [end, sec.blocks.length - 1]));
349|  return { ...sec, blocks: sec.blocks.slice(0, end) };
350|}
351|
352|const IMAGE_PLACEHOLDER = /^(image|img|illus|illustration|fig)[ _-]?\d+[a-z]?$/i;
353|
354|// Rule 11: inside content, drop headings, illustration and image
355|// placeholders, Gutenberg page anchors, and a repeated chapter title in
356|// the first two body blocks (Cottage Folk "THE HOPPERS"). Oz chapters
357|// start with prose, so the duplicate-title drop never fires there.
358|export function toParagraphs(sec: RawSection, title: string): string[] {
359|  const normTitle = normalizeTitle(title);
360|  const body = sec.blocks.filter((b) => !b.heading);
361|  let skip = 0;
362|  if (normTitle.length > 0 && sec.blocks.some((b) => b.heading)) {
363|    for (const b of body.slice(0, 2)) {
364|      if (normalizeTitle(b.text) === normTitle) skip += 1;
365|      else break;
366|    }
367|  }
368|  return body
369|    .slice(skip)
370|    .filter(
371|      (b) =>
372|        !/^\[illustration/i.test(b.text.trim()) &&
373|        !IMAGE_PLACEHOLDER.test(b.text.trim()) &&
374|        !/^\[pg\s*\d+\]$/i.test(b.text.trim()),
375|    )
376|    .map((b) => b.text);
377|}

