5|export function countWords(text: string): number {
6|  return text.split(/\s+/).filter((w) => w.length > 0).length;
7|}
8|
9|export function sectionWords(sec: Pick<RawSection, "blocks">): number {
10|  return sec.blocks.reduce((n, b) => n + countWords(b.text), 0);
11|}
12|
13|export function short(text: string, max: number): string {
14|  return text.length <= max ? text : text.slice(0, max);
15|}
