18|  sec: RawSection,
19|  rule: string,
20|  kind: string,
21|  reason: string,
22|  blockRange: [number, number] | null = null,
23|): RemovedItem {
24|  const texts =
25|    blockRange === null ? sec.blocks.map((b) => b.text) : sec.blocks.slice(blockRange[0], blockRange[1] + 1).map((b) => b.text);
26|  return {
27|    sectionId: sec.id,
28|    blockRange,
29|    kind,
30|    reason: short(reason, 120),
31|    rule,
32|    words: texts.reduce((n, t) => n + countWords(t), 0),
33|    preview: short(texts[0] ?? "", 120),
34|  };
35|}
