41|
42|// Rule 2: Standard Ebooks types are exact. Keep chapters and bodymatter,
43|// drop front/backmatter. Gutenberg files carry no types and pass through.
44|export function ruleEpubType(sec: RawSection): { kind: string; reason: string } | null {
45|  const types = sec.types.map((t) => t.toLowerCase());
46|  if (types.includes("chapter") || types.includes("bodymatter")) return null;
47|  if (types.includes("frontmatter") || types.includes("backmatter")) {
48|    return { kind: "front_matter", reason: `epub:type ${sec.types.join(" ")}` };
49|  }
50|  return null;
51|}
52|
53|// Rule 8 (runs early): a heading-free fragment of at most 30 words whose
54|// docTitle matches the previous kept section continues that section. Runs
55|// before empty/keyword rules so "Holmesly." merges instead of vanishing.
56|export function mergeContinuations(
57|  sections: RawSection[],
58|  merged: CleanReport["merged"],
59|): RawSection[] {
60|  const kept: RawSection[] = [];
61|  for (const sec of sections) {
62|    const prev = kept[kept.length - 1];
